INSERT INTO public.crm_plantillas VALUES (1, 'Encuesta de Satisfacción Post-Consumo (WhatsApp)', 'encuesta_satisfaccion_wa', 'whatsapp', 'encuesta', NULL, '¡Hola {nombre}! 🍣 Gracias por visitarnos en {restaurante}. Tu opinión es vital para nuestro equipo. ¿Nos regalas 30 segundos calificando tu experiencia?
INSERT INTO public.crm_plantillas VALUES (2, 'Confirmación de Reserva (WhatsApp)', 'reserva_confirmada_wa', 'whatsapp', 'reserva', NULL, '¡Hola {nombre}! 🛎️ Tu reserva en {restaurante} está *CONFIRMADA*.
INSERT INTO public.crm_plantillas VALUES (3, 'Recordatorio 2 Horas Antes de Reserva (WhatsApp)', 'reserva_recordatorio_wa', 'whatsapp', 'reserva', NULL, '¡Hola {nombre}! ⏱️ Te recordamos que hoy tienes una reserva en {restaurante} a las *{hora_reserva}* (Mesa {mesa}). Tu mesa y nuestro equipo están listos para recibirte. ¡Nos vemos pronto!', 'reserva_recordatorio_2h_v1', 'es', true, '2026-10-03 18:41:46', '2026-10-03 18:41:46');
INSERT INTO public.crm_plantillas VALUES (4, 'Reactivación de Clientes Inactivos (WhatsApp)', 'winback_cliente_inactivo_wa', 'whatsapp', 'marketing', NULL, '¡Hola {nombre}! 🍣 Hace tiempo que no te vemos en {restaurante} y te extrañamos. Queremos invitarte una copa de cortesía o un postre especial en tu próxima visita mencionando el código *VUELVEVIP*. ¡Reserva tu mesa aquí: {url_reserva}!', 'winback_inactivos_v1', 'es', true, '2026-10-03 18:41:46', '2026-10-03 18:41:46');
INSERT INTO public.crm_plantillas VALUES (5, 'Felicitación de Cumpleaños VIP (WhatsApp)', 'cumpleanos_cliente_wa', 'whatsapp', 'cumpleanos', NULL, '🎂 ¡Feliz Cumpleaños {nombre}! 🎉 De parte de todo el equipo de {restaurante} te deseamos un día extraordinario. Ven a celebrar esta semana con nosotros y el postre de la casa va por nuestra cuenta. ¡Te esperamos!', 'cumpleanos_vip_v1', 'es', true, '2026-10-03 18:41:46', '2026-10-03 18:41:46');
INSERT INTO public.crm_plantillas VALUES (6, 'Encuesta de Satisfacción Post-Consumo (Email)', 'encuesta_satisfaccion_email', 'email', 'encuesta', '¿Cómo estuvo tu experiencia en RestoMaster? 🍣 Califícanos', '<p>Hola <strong>{nombre}</strong>,</p><p>Muchas gracias por visitarnos en {restaurante}. Esperamos que hayas disfrutado de nuestros platos y la atención de nuestro equipo.</p><p>¿Nos ayudas con 30 segundos de tu tiempo para evaluar nuestro servicio? Al responder sumarás <strong>+50 puntos VIP</strong> a tu cuenta de fidelización.</p><p style=''text-align: center; margin: 25px 0;''><a href=''{url_encuesta}'' style=''background-color: #ef4444; color: #ffffff; padding: 12px 24px; border-radius: 8px; text-decoration: none; font-weight: bold;''>Calificar mi Experiencia ⭐</a></p><p>¡Gracias por ser parte de nuestra comunidad!</p>', NULL, 'es', true, '2026-10-03 18:41:46', '2026-10-03 18:41:46');
INSERT INTO public.crm_plantillas VALUES (7, 'Plantilla: Alerta Inmediata por Encuesta Negativa', 'alerta-inmediata-por-encuesta-negativa_ofedhj', 'whatsapp', 'fidelizacion', 'Alerta Inmediata por Encuesta Negativa', 'Estimado(a) {{nombre}}, lamentamos que tu experiencia no haya sido perfecta. Nuestro gerente general se comunicará contigo personalmente para subsanarlo de inmediato.', NULL, 'es', true, '2026-10-03 19:30:06', '2026-10-03 19:30:06');
